class Solution {
public:
    vector<int> solve(vector<int>& nums, vector<vector<int>>& queries) {
        long long MOD = 1e9 + 7;
        int n = nums.size();
        int B = sqrt(n) + 1;
        vector<vector<int>> pre(B, vector<int>(n, 0));
        for (int step = 1; step < B; step++) {
            for (int i = n - 1; i >= 0; i--) {
                int nxt = (i + step < n) ? pre[step][i + step] : 0;
                pre[step][i] = (nums[i] + nxt) % MOD;
            }
        }
        vector<int> ans;
        ans.reserve(queries.size());
        for (const auto& q : queries) {
            int x = q[0], y = q[1];
            if (y < B) {
                ans.push_back(pre[y][x]);
            } else {
                long long tot = 0;
                for (int curr = x; curr < n; curr += y) {
                    tot = (tot + nums[curr]) % MOD;
                }
                ans.push_back(tot);
            }
        }
        return ans;
    }
};

class Solution {
    public int[] solve(int[] nums, int[][] queries) {
        long MOD = 1_000_000_007L;
        int n = nums.length;
        int B = (int)Math.sqrt(n) + 1;
        int[][] pre = new int[B][n];
        for (int step = 1; step < B; step++) {
            for (int i = n - 1; i >= 0; i--) {
                int nxt = (i + step < n) ? pre[step][i + step] : 0;
                pre[step][i] = (int)((nums[i] + nxt) % MOD);
            }
        }
        int[] ans = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int x = queries[q][0];
            int y = queries[q][1];
            if (y < B) {
                ans[q] = pre[y][x];
            } else {
                long tot = 0;
                for (int curr = x; curr < n; curr += y) {
                    tot = (tot + nums[curr]) % MOD;
                }
                ans[q] = (int)tot;
            }
        }
        return ans;
    }
}

var solve = function(nums, queries) {
    const MOD = 1000000007;
    const n = nums.length;
    const B = Math.floor(Math.sqrt(n)) + 1;
    const pre = Array.from({ length: B }, () => new Int32Array(n));
    for (let step = 1; step < B; step++) {
        for (let i = n - 1; i >= 0; i--) {
            const nxt = (i + step < n) ? pre[step][i + step] : 0;
            pre[step][i] = (nums[i] + nxt) % MOD;
        }
    }
    const ans = new Array(queries.length);
    for (let q = 0; q < queries.length; q++) {
        const [x, y] = queries[q];
        if (y < B) {
            ans[q] = pre[y][x];
        } else {
            let tot = 0;
            for (let curr = x; curr < n; curr += y) {
                tot = (tot + nums[curr]) % MOD;
            }
            ans[q] = tot;
        }
    }
    return ans;
};
